from flask import Flask, render_template, request, redirect, url_for, session, abort
from dataclasses import dataclass, field
from typing import Dict, List


@dataclass
class Product:
    id: int
    name: str
    price: float
    stock: int
    active: bool = True


@dataclass
class Customer:
    id: int
    name: str
    email: str


@dataclass
class CartItem:
    product_id: int
    quantity: int


@dataclass
class Order:
    id: int
    customer_id: int
    items: List[CartItem]
    status: str = 'new'


class Store:
    def __init__(self):
        self.products: Dict[int, Product] = {
            1: Product(1, 'Sample Product', 19.99, 10, True)
        }
        self.customers: Dict[int, Customer] = {}
        self.orders: Dict[int, Order] = {}
        self.next_customer_id = 1
        self.next_order_id = 1


store = Store()


def create_app():
    app = Flask(__name__)
    app.secret_key = 'dev-secret-key'

    @app.get('/')
    def home():
        return render_template('home.html', products=list(store.products.values()))

    @app.post('/register')
    def register():
        name = request.form.get('name', '').strip()
        email = request.form.get('email', '').strip().lower()
        if not name or not email or '@' not in email:
            abort(400, 'Invalid customer details')
        if any(c.email == email for c in store.customers.values()):
            abort(400, 'Duplicate customer')
        cid = store.next_customer_id
        store.next_customer_id += 1
        store.customers[cid] = Customer(cid, name, email)
        session['customer_id'] = cid
        return redirect(url_for('home'))

    @app.get('/cart')
    def cart():
        return render_template('cart.html', cart=session.get('cart', []), products=store.products)

    @app.post('/cart/add/<int:product_id>')
    def cart_add(product_id):
        product = store.products.get(product_id)
        if not product or not product.active:
            abort(404)
        cart = session.get('cart', [])
        for item in cart:
            if item['product_id'] == product_id:
                if item['quantity'] + 1 > product.stock:
                    abort(400, 'Not enough stock')
                item['quantity'] += 1
                session['cart'] = cart
                return redirect(url_for('cart'))
        if product.stock < 1:
            abort(400, 'Not enough stock')
        cart.append({'product_id': product_id, 'quantity': 1})
        session['cart'] = cart
        return redirect(url_for('cart'))

    @app.post('/checkout')
    def checkout():
        customer_id = session.get('customer_id')
        if not customer_id:
            abort(400, 'Customer login required')
        cart = session.get('cart', [])
        if not cart:
            abort(400, 'Cart is empty')
        for item in cart:
            product = store.products.get(item['product_id'])
            if not product or product.stock < item['quantity'] or not product.active:
                abort(400, 'Cart cannot be confirmed')
        for item in cart:
            store.products[item['product_id']].stock -= item['quantity']
        oid = store.next_order_id
        store.next_order_id += 1
        order_items = [CartItem(i['product_id'], i['quantity']) for i in cart]
        store.orders[oid] = Order(oid, customer_id, order_items)
        session['cart'] = []
        return render_template('order.html', order=store.orders[oid], products=store.products)

    @app.get('/admin')
    def admin():
        return render_template('admin.html', products=list(store.products.values()), customers=list(store.customers.values()), orders=list(store.orders.values()))

    return app
EOF

